I'll create 3 different design approaches for a Document Summary/Index component.

```vue client/src/components/document/DocumentSummary.vue
<script setup>
import MarkdownViewer from '../MarkdownViewer.vue'
</script>

<template>
  <!-- Design 1: Collapsible sidebar TOC with anchored headings -->
  <div class="relative" v-if="headings.length >= minHeadings">
    <button
      @click="open = !open"
      class="flex items-center gap-2 text-xs font-semibold text-base-content/60 hover:text-base-content mb-1 transition-colors"
    >
      <span class="text-base">📋</span>
      <span>{{ open ? 'Hide' : 'Show' }} Contents</span>
      <span class="text-base-content/40">({{ headings.length }})</span>
      <svg
        class="w-3 h-3 transition-transform"
        :class="open && 'rotate-180'"
        fill="none" stroke="currentColor" viewBox="0 0 24 24"
      >
        <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 9l-7 7-7-7"/>
      </svg>
    </button>

    <transition name="toc-slide">
      <div
        v-if="open"
        class="bg-base-200 border border-base-300 rounded-lg px-4 py-3 mb-4 max-h-64 overflow-y-auto"
      >
        <p class="text-xs font-bold text-base-content/50 uppercase tracking-widest mb-2">Table of Contents</p>
        <ul class="space-y-0.5">
          <li
            v-for="(h, i) in headings"
            :key="i"
            :style="{ paddingLeft: (h.level - 1) * 12 + 'px' }"
          >
            <a
              :href="`#${h.anchor}`"
              class="text-sm text-primary hover:underline hover:text-primary-focus block py-0.5 truncate"
              @click.prevent="scrollTo(h.anchor)"
            >
              <span class="text-base-content/30 mr-1 text-xs">{{ levelIcon(h.level) }}</span>
              {{ h.text }}
            </a>
          </li>
        </ul>
      </div>
    </transition>
  </div>
</template>

<script>
// Extracts headings from markdown text and builds a TOC
export default {
  name: 'DocumentSummary',
  props: {
    content: { type: String, default: '' },
    minHeadings: { type: Number, default: 3 }
  },
  data() {
    return {
      open: false
    }
  },
  computed: {
    headings() {
      const lines = (this.content || '').split('\n')
      return lines
        .map(line => {
          const m = line.match(/^(#{1,6})\s+(.+)$/)
          if (!m) return null
          const text = m[2].trim()
          return {
            level: m[1].length,
            text,
            anchor: text.toLowerCase().replace(/[^\w\s-]/g, '').replace(/\s+/g, '-')
          }
        })
        .filter(Boolean)
    }
  },
  methods: {
    levelIcon(level) {
      return ['#', '##', '###', '####', '#####', '######'][level - 1] || '#'
    },
    scrollTo(anchor) {
      const el = document.getElementById(anchor)
      el?.scrollIntoView({ behavior: 'smooth', block: 'start' })
    }
  }
}
</script>
