Now integrate it into `Document.vue`:

```vue client/src/components/document/Document.vue
<script setup>
import MarkdownViewer from '../MarkdownViewer.vue'
import Code from '../Code.vue'
import DocumentSummary from './DocumentSummary.vue'
</script>

<template>
  <div class="flex flex-col @container/document">
    <!-- Optional summary/index: only shown when doc has enough headings -->
    <DocumentSummary :content="content" :min-headings="3" />

    <div v-for="block in blocks" :key="block.hash">
      <MarkdownViewer
        :files="files"
        v-if="block.renderer === 'md'"
        :text="block.content"
        @add-file="$emit('add-file', $event)"
      />
      <Code
        :class="!block.finished && 'border border-dashed border-slate-400'"
        :text="block.content"
        :text-language="block.type"
        :fileName="block.fileName"
        :files="files"
        :project="docProject"
        :finished="block.finished"
        :chat="chat"
        @generate-code="$emit('generate-code', $event)"
        @reload-file="$emit('reload-file', { file: $event, message })"
        @open-file="$emit('open-file', $event)"
        @save-file="$emit('save-file', $event)"
        @add-file="$emit('add-file', $event)"
        @edit-message="$emit('edit-message', $event)"
        @sub-task="$emit('sub-task', $event)"
        v-else
      />
      <div class="chat-footer opacity-50 text-xs font-bold" v-if="!block.finished">
        loading <span class="loading loading-spinner"></span>
      </div>
    </div>
  </div>
</template>

<script>
function generateHash(str) {
  let hash = 0
  for (const char of str) {
    hash = (hash << 5) - hash + char.charCodeAt(0)
    hash |= 0
  }
  return hash
}

function getRenderer(blockType) {
  if (['markdown', 'md'].includes(blockType)) return 'md'
  if (['html'].includes(blockType)) return blockType
  return 'code'
}

function parseContent(content, loading) {
  const blocks = []
  const lines = content.split('\n')
  let currentType = 'markdown'
  let currentContent = []
  let currentFileName = ''
  let nestingDepth = 0

  function setAllFinished() {
    blocks.forEach(b => b.finished = true)
  }

  function addBlock() {
    const blockContent = currentContent.join('\n')
    const hash = generateHash(blockContent)
    setAllFinished()
    blocks.push({
      type: currentType,
      content: blockContent,
      hash,
      fileName: currentFileName,
      renderer: getRenderer(currentType),
      finished: false
    })
    currentType = 'markdown'
    currentContent = []
    currentFileName = ''
  }

  for (const line of lines) {
    const openMatch = line.match(/^```(\w+)\s*(.*)$/)
    const closeMatch = line === '```'

    if (nestingDepth === 0 && openMatch) {
      if (currentContent.length) addBlock()
      nestingDepth = 1
      currentType = openMatch[1]
      currentFileName = openMatch[2] || ''
    } else if (nestingDepth === 1 && closeMatch) {
      addBlock()
      nestingDepth = 0
    } else if (nestingDepth >= 1 && openMatch) {
      nestingDepth++
      currentContent.push(line)
    } else if (nestingDepth > 1 && closeMatch) {
      nestingDepth--
      currentContent.push(line)
    } else {
      currentContent.push(line)
    }
  }

  if (currentContent.length) addBlock()
  if (!loading) setAllFinished()
  return blocks
}

export default {
  props: ['content', 'files', 'project', 'chat', 'loading'],
  emits: ['generate-code', 'reload-file', 'open-file', 'save-file', 'add-file', 'edit-message', 'sub-task'],
  computed: {
    blocks() {
      return parseContent(this.content || '', this.loading)
    },
    docProject() {
      return this.project || this.$project
    }
  }
}
</script>
```

---

### Summary of the 3 designs:

| | Design 1 | Design 2 | Design 3 |
|---|---|---|---|
| **Style** | Collapsible dropdown TOC | Pill/chip quick-jump bar | Mini-map + stats panel |
| **UX** | Click toggle → scrollable list | Always visible inline chips | Compact bar + word count/read time |
| **Best for** | Long structured docs | Medium docs, quick nav | Reference docs with stats |

All three share the same `minHeadings` prop (default `3`) so short messages show nothing automatically.

Looking at the code, I need to add IDs to the headings rendered in `Document.vue` → `MarkdownViewer.vue` so `DocumentSummary.scrollTo` can find them. The best approach is to add `id` attributes to heading elements in `MarkdownViewer.vue`. Let me check the flow and update `DocumentSummary` to scroll within the chat entry's content area.

The key changes needed:
1. **`MarkdownViewer.vue`** - Add `id` anchors to rendered headings
2. **`DocumentSummary.vue`** - Pass a scroll container ref or search within parent

```vue client/src/components/MarkdownViewer.vue
<script setup>
import { marked } from 'marked'
</script>

<template>
  <div class="markdown-viewer" ref="container" v-html="renderedContent"></div>
</template>

<script>
import { marked } from 'marked'

export default {
  props: ['text', 'files'],
  emits: ['add-file'],
  computed: {
    renderedContent() {
      if (!this.text) return ''
      // Custom renderer to add id anchors to headings
      const renderer = new marked.Renderer()
      renderer.heading = (text, level) => {
        const anchor = text
          .toLowerCase()
          .replace(/[^\w\s-]/g, '')
          .replace(/\s+/g, '-')
        return `<h${level} id="${anchor}" class="heading-anchor">${text}</h${level}>`
      }
      return marked(this.text, { renderer })
    }
  }
}
</script>
```

Now update `DocumentSummary` to scroll the nearest scrollable ancestor to the heading:

```vue client/src/components/document/DocumentSummary.vue
