    </transition>
  </div>
</template>

<script>
export default {
  name: 'DocumentSummary',
  props: {
    content: { type: String, default: '' },
    minHeadings: { type: Number, default: 3 }
  },
  data() {
    return {
      open: false
    }
  },
  computed: {
    headings() {
      const lines = (this.content || '').split('\n')
      return lines
        .map(line => {
          const m = line.match(/^(#{1,6})\s+(.+)$/)
          if (!m) return null
          const text = m[2].trim()
          return {
            level: m[1].length,
            text,
            anchor: text.toLowerCase().replace(/[^\w\s-]/g, '').replace(/\s+/g, '-')
          }
        })
        .filter(Boolean)
    }
  },
  methods: {
    levelIcon(level) {
      return ['#', '##', '###', '####', '#####', '######'][level - 1] || '#'
    },
    // Find the nearest scrollable ancestor of a given element
    findScrollableParent(el) {
      if (!el) return window
      const style = window.getComputedStyle(el)
      const overflowY = style.overflowY
      const isScrollable = (overflowY === 'auto' || overflowY === 'scroll') && el.scrollHeight > el.clientHeight
      if (isScrollable) return el
      return this.findScrollableParent(el.parentElement)
    },
    scrollTo(anchor) {
      const target = document.getElementById(anchor)
      if (!target) return
      const scrollParent = this.findScrollableParent(target)
      if (scrollParent === window) {
        target.scrollIntoView({ behavior: 'smooth', block: 'start' })
        return
      }
      // Scroll within the container so the heading is visible
      const containerTop = scrollParent.getBoundingClientRect().top
      const targetTop = target.getBoundingClientRect().top
      const offset = targetTop - containerTop + scrollParent.scrollTop - 8
      scrollParent.scrollTo({ top: offset, behavior: 'smooth' })
    }
  }
}
</script>
```

### Key changes:

1. **`MarkdownViewer.vue`** — Custom `marked` renderer adds `id="${anchor}"` to every heading element using the same anchor slug algorithm as `DocumentSummary`, so `document.getElementById(anchor)` will reliably find the target

2. **`DocumentSummary.vue`** — `scrollTo` now:
   - Finds the element by `id` 
   - Walks up the DOM via `findScrollableParent()` to locate the nearest `overflow: auto/scroll` container (the chat message scroll area)
   - Calculates the correct `scrollTop` offset relative to that container and smoothly scrolls to it — rather than using `scrollIntoView` which may scroll the wrong container

Looking at the code, I need to:

1. Generate a unique `documentId` in `Document.vue` and pass it down
2. Use the `documentId` as a prefix for heading anchors in `MarkdownViewer.vue`
3. Update `DocumentSummary.vue` to use the same prefixed anchors

