        v-if="open"
        class="bg-base-200 border border-base-300 rounded-lg px-4 py-3 mb-4 max-h-64 overflow-y-auto"
      >
        <p class="text-xs font-bold text-base-content/50 uppercase tracking-widest mb-2">Table of Contents</p>
        <ul class="space-y-0.5">
          <li
            v-for="(h, i) in headings"
            :key="i"
            :style="{ paddingLeft: (h.level - 1) * 12 + 'px' }"
          >
            <a
              :href="`#${h.anchor}`"
              class="text-sm text-primary hover:underline hover:text-primary-focus block py-0.5 truncate"
              @click.prevent="scrollTo(h.anchor)"
            >
              <span class="text-base-content/30 mr-1 text-xs">{{ levelIcon(h.level) }}</span>
              {{ h.text }}
            </a>
          </li>
        </ul>
      </div>
    </transition>
  </div>
</template>

<script>
export default {
  name: 'DocumentSummary',
  props: {
    content: { type: String, default: '' },
    minHeadings: { type: Number, default: 3 },
    // Scoping id — must match the documentId used in MarkdownViewer
    documentId: { type: String, default: '' },
    scrollContainer: { type: Object, default: null }
  },
  data() {
    return {
      open: false
    }
  },
  computed: {
    headings() {
      const lines = (this.content || '').split('\n')
      return lines
        .map(line => {
          const m = line.match(/^(#{1,6})\s+(.+)$/)
          if (!m) return null
          const text = m[2].trim()
          const slug = text
            .toLowerCase()
            .replace(/[^\w\s-]/g, '')
            .trim()
            .replace(/\s+/g, '-')
          // Prefix anchor with documentId to match MarkdownViewer rendered ids
          const anchor = this.documentId ? `${this.documentId}-${slug}` : slug
          return { level: m[1].length, text, anchor }
        })
        .filter(Boolean)
    }
  },
  methods: {
    levelIcon(level) {
      return ['#', '##', '###', '####', '#####', '######'][level - 1] || '#'
    },
    findScrollableParent(el) {
      if (!el || el === document.body) return null
      const { overflowY } = window.getComputedStyle(el)
      const isScrollable = (overflowY === 'auto' || overflowY === 'scroll') && el.scrollHeight > el.clientHeight
      return isScrollable ? el : this.findScrollableParent(el.parentElement)
    },
    scrollTo(anchor) {
      const target = document.getElementById(anchor)
      if (!target) return

      const container = this.scrollContainer
        || this.findScrollableParent(target)
        || window

      if (container === window) {
        target.scrollIntoView({ behavior: 'smooth', block: 'start' })
        return
      }

      const containerRect = container.getBoundingClientRect()
      const targetRect = target.getBoundingClientRect()
      const offset = targetRect.top - containerRect.top + container.scrollTop - 8
      container.scrollTo({ top: offset, behavior: 'smooth' })
    }
  }
}
</script>
